#include "config_manager.h"

#include <stdio.h>
#include <string.h>

#include "sdkconfig.h"
#include "esp_log.h"
#include "freertos/FreeRTOS.h"
#include "freertos/semphr.h"
#include "nvs.h"
#include "nvs_flash.h"

/* Generated by Kconfig (main/Kconfig.projbuild); defaults keep builds working
 * if the options are ever removed. */
#ifndef CONFIG_SIP_PHONE_WIFI_SSID
#define CONFIG_SIP_PHONE_WIFI_SSID ""
#endif
#ifndef CONFIG_SIP_PHONE_WIFI_PASSWORD
#define CONFIG_SIP_PHONE_WIFI_PASSWORD ""
#endif

static const char *TAG = "SYSTEM";

#define NVS_NAMESPACE "phone_cfg"
#define NVS_KEY       "config"

static phone_config_t s_config;
static SemaphoreHandle_t s_lock;
static bool s_initialized;

static void copy_str(char *dst, size_t dst_len, const char *src)
{
    if (dst_len == 0) {
        return;
    }
    snprintf(dst, dst_len, "%s", (src != NULL) ? src : "");
}

static void config_defaults(phone_config_t *cfg)
{
    memset(cfg, 0, sizeof(*cfg));
    cfg->version = CONFIG_SCHEMA_VERSION;

    cfg->wifi.use_dhcp = true;
    copy_str(cfg->wifi.ssid, sizeof(cfg->wifi.ssid), CONFIG_SIP_PHONE_WIFI_SSID);
    copy_str(cfg->wifi.password, sizeof(cfg->wifi.password), CONFIG_SIP_PHONE_WIFI_PASSWORD);
    copy_str(cfg->wifi.ip, sizeof(cfg->wifi.ip), "192.168.4.150");
    copy_str(cfg->wifi.netmask, sizeof(cfg->wifi.netmask), "255.255.255.0");
    copy_str(cfg->wifi.gateway, sizeof(cfg->wifi.gateway), "192.168.4.1");
    copy_str(cfg->wifi.dns, sizeof(cfg->wifi.dns), "192.168.4.1");

    /* Test values from the brief; everything is editable at runtime. */
    copy_str(cfg->sip.server, sizeof(cfg->sip.server), "192.168.4.29");
    cfg->sip.port = 5060;
    copy_str(cfg->sip.username, sizeof(cfg->sip.username), "101");
    copy_str(cfg->sip.auth_id, sizeof(cfg->sip.auth_id), "101");
    copy_str(cfg->sip.display_name, sizeof(cfg->sip.display_name), "XIAO Phone");
    copy_str(cfg->sip.extension, sizeof(cfg->sip.extension), "101");
    cfg->sip.transport = SIP_TRANSPORT_UDP;
    cfg->sip.register_expiry_s = 300;
    cfg->sip.dtmf_mode = DTMF_MODE_RFC2833;
    cfg->sip.prefer_pcma = false;

    cfg->audio.mic_gain_db = 0;
    cfg->audio.speaker_volume = 80;
    cfg->audio.jitter_frames = 10;
    cfg->audio.packet_ms = 20;
    cfg->audio.noise_reduction = true;
    cfg->audio.aec_enabled = false;

    copy_str(cfg->phone.default_number, sizeof(cfg->phone.default_number), "101");
    copy_str(cfg->phone.display_name, sizeof(cfg->phone.display_name), "XIAO Phone");
    cfg->phone.auto_answer = false;
    cfg->phone.auto_answer_delay_ms = 2000;
    cfg->phone.ring_duration_s = 30;
    cfg->phone.call_timeout_s = 60;

    copy_str(cfg->system.device_name, sizeof(cfg->system.device_name), "XIAO SIP Phone");
    copy_str(cfg->system.hostname, sizeof(cfg->system.hostname), "xiao-sip-phone");
    /* Default credentials: change them from the web UI once it exists. */
    copy_str(cfg->system.web_user, sizeof(cfg->system.web_user), "admin");
    copy_str(cfg->system.web_password, sizeof(cfg->system.web_password), "admin");
}

esp_err_t config_manager_load(void)
{
    nvs_handle_t handle;
    esp_err_t err = nvs_open(NVS_NAMESPACE, NVS_READONLY, &handle);

    if (err == ESP_ERR_NVS_NOT_FOUND) {
        ESP_LOGI(TAG, "[SYSTEM] No stored configuration, writing defaults");
        config_defaults(&s_config);
        return config_manager_save();
    }
    if (err != ESP_OK) {
        ESP_LOGE(TAG, "[SYSTEM] nvs_open failed: %s", esp_err_to_name(err));
        return err;
    }

    phone_config_t loaded;
    size_t len = sizeof(loaded);
    err = nvs_get_blob(handle, NVS_KEY, &loaded, &len);
    nvs_close(handle);

    if (err != ESP_OK || len != sizeof(loaded) || loaded.version != CONFIG_SCHEMA_VERSION) {
        ESP_LOGW(TAG, "[SYSTEM] Stored configuration missing or incompatible, restoring defaults");
        config_defaults(&s_config);
        return config_manager_save();
    }

    memcpy(&s_config, &loaded, sizeof(s_config));
    ESP_LOGI(TAG, "[SYSTEM] Configuration loaded from NVS");
    return ESP_OK;
}

esp_err_t config_manager_save(void)
{
    nvs_handle_t handle;
    esp_err_t err = nvs_open(NVS_NAMESPACE, NVS_READWRITE, &handle);
    if (err != ESP_OK) {
        ESP_LOGE(TAG, "[SYSTEM] nvs_open for save failed: %s", esp_err_to_name(err));
        return err;
    }

    err = nvs_set_blob(handle, NVS_KEY, &s_config, sizeof(s_config));
    if (err == ESP_OK) {
        err = nvs_commit(handle);
    }
    nvs_close(handle);

    if (err != ESP_OK) {
        ESP_LOGE(TAG, "[SYSTEM] Configuration save failed: %s", esp_err_to_name(err));
    }
    return err;
}

esp_err_t config_manager_init(void)
{
    if (s_initialized) {
        return ESP_OK;
    }

    if (s_lock == NULL) {
        s_lock = xSemaphoreCreateMutex();
    }
    if (s_lock == NULL) {
        return ESP_ERR_NO_MEM;
    }

    esp_err_t err = nvs_flash_init();
    if (err == ESP_ERR_NVS_NO_FREE_PAGES || err == ESP_ERR_NVS_NEW_VERSION_FOUND) {
        ESP_LOGW(TAG, "[SYSTEM] NVS unusable (%s), erasing", esp_err_to_name(err));
        err = nvs_flash_erase();
        if (err == ESP_OK) {
            err = nvs_flash_init();
        }
    }
    if (err != ESP_OK) {
        ESP_LOGE(TAG, "[SYSTEM] NVS init failed: %s", esp_err_to_name(err));
        return err;
    }

    err = config_manager_load();
    if (err == ESP_OK) {
        s_initialized = true;
    }
    return err;
}

const phone_config_t *config_manager_get(void)
{
    return &s_config;
}

bool config_manager_is_ready(void)
{
    return s_initialized;
}

esp_err_t config_manager_set(const phone_config_t *cfg)
{
    if (cfg == NULL) {
        return ESP_ERR_INVALID_ARG;
    }
    if (s_lock == NULL || xSemaphoreTake(s_lock, pdMS_TO_TICKS(200)) != pdTRUE) {
        return ESP_ERR_TIMEOUT;
    }

    memcpy(&s_config, cfg, sizeof(s_config));

    esp_err_t err = config_manager_save();
    xSemaphoreGive(s_lock);

    if (err == ESP_OK) {
        ESP_LOGI(TAG, "[SYSTEM] Configuration updated and saved");
    }
    return err;
}

esp_err_t config_manager_factory_reset(void)
{
    esp_err_t err = nvs_flash_erase();
    if (err != ESP_OK) {
        ESP_LOGE(TAG, "[SYSTEM] Factory reset failed: %s", esp_err_to_name(err));
    }

    /* Re-init so the next save works without a reboot. */
    if (err == ESP_OK) {
        err = nvs_flash_init();
    }

    config_defaults(&s_config);
    if (err == ESP_OK) {
        err = config_manager_save();
    }

    if (err == ESP_OK) {
        ESP_LOGI(TAG, "[SYSTEM] Factory reset complete, defaults restored");
    }
    return err;
}
